/* Œconomia — Entraînement : thème « Inégalités et répartition » (24 exercices, trois niveaux). */
(function () {
  const X = OEC.exo, { rnd, pick, fmt } = X;
  const P = (...a) => a.map((t) => `<p>${t}</p>`).join("");
  const median = (arr) => { const s = [...arr].sort((a, b) => a - b), n = s.length; return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2; };
  /* Impôt par tranches : 0 % jusqu’à 20 000, 10 % de 20 000 à 50 000, 20 % de 50 000 à 100 000, 30 % au-delà */
  const TR = [[20000, 0], [50000, 0.1], [100000, 0.2], [Infinity, 0.3]];
  const impot = (r) => { let t = 0, prev = 0; for (const [lim, taux] of TR) { if (r > prev) t += (Math.min(r, lim) - prev) * taux; prev = lim; } return t; };

  const apres = (p) => Math.round(p.r * (100 - Math.round(p.ti * 100)) / 100 / (p.p + p.tr) * 10 + 1e-9) / 10;

  X.theme({ id: "inegalites", nom: "Inégalités et répartition",
    intro: "Comment mesurer les inégalités de revenus et de patrimoine, comment l’impôt et les transferts les modifient-ils, et quelles inégalités sont justes ? Ces exercices vous entraînent à calculer des indicateurs, à comprendre la progressivité de l’impôt et à discuter des grandes théories de la justice.",
    notions: ["courbe-kuznets", "r-g", "capabilites", "optimum-pareto", "plus-value", "rente"] });

  X.add([
  /* =========================== NIVEAU 1 : DÉCOUVERTE =========================== */
  { id: "in1-revenu-patrimoine", theme: "inegalites", niveau: 1, type: "qcm", notion: "r-g",
    titre: "Revenu ou patrimoine ?", competence: "Distinguer un flux d’un stock.",
    enonce: P("Laquelle de ces affirmations décrit correctement la différence entre revenu et patrimoine ?"),
    options: ["Le revenu est ce qu’on possède à un moment donné ; le patrimoine, ce qu’on gagne chaque année en travaillant.", "Le revenu est ce qu’on perçoit sur une période ; le patrimoine est ce qu’on possède à une date donnée, dettes déduites.", "Le revenu et le patrimoine sont deux mots pour la même chose, mesurée à deux moments différents.", "Le patrimoine ne comprend que l’argent sur un compte bancaire et les titres cotés en bourse."], c: 1, pourquoi: ["C’est l’inverse : le revenu est un flux perçu pendant une période ; le patrimoine, un stock possédé à une date.", null, "On peut avoir un revenu élevé et peu de patrimoine, ou l’inverse : ce sont deux grandeurs différentes, l’une est un flux, l’autre un stock.", "Le patrimoine comprend aussi le logement, les actions, les terrains ou une entreprise, moins les dettes."],
    explication: P("Le <b>revenu</b> est un <b>flux</b> : ce qu’on perçoit pendant une période, par exemple un salaire mensuel ou des intérêts annuels. Le <b>patrimoine</b> est un <b>stock</b> : la valeur de tout ce qu’on possède à une date donnée, net des dettes.", "Les inégalités de patrimoine sont toujours bien plus fortes que les inégalités de revenus, notamment à cause de l’héritage. En Suisse, le patrimoine est l’un des plus concentrés d’Europe.") },

  { id: "in1-s80s20", theme: "inegalites", niveau: 1, type: "calcul",
    titre: "Le rapport entre les plus riches et les plus pauvres", competence: "Calculer un indicateur simple d’inégalité.",
    gen: () => ({ r: rnd(120, 190) * 1000, p: rnd(25, 45) * 1000 }),
    enonce: (p) => P(`Dans un pays, le revenu moyen des 20 % les plus aisés est de <b>${fmt(p.r)} francs</b> par an, et celui des 20 % les plus modestes de <b>${fmt(p.p)} francs</b>.`, "Calculez le rapport entre les deux (arrondi à une décimale)."),
    champs: [{ label: "Rapport", unite: "fois", tol: 0.1 }],
    reponses: (p) => [Math.round((p.r / p.p) * 10) / 10],
    indice: "Divisez le revenu des plus aisés par celui des plus modestes.",
    correction: (p) => P(`Rapport = ${fmt(p.r)} ÷ ${fmt(p.p)}`, `≈ <b>${fmt(p.r / p.p, 1)}</b>.`, `Les 20 % les plus aisés gagnent en moyenne ${fmt(p.r / p.p, 1)} fois plus que les 20 % les plus modestes. Cet indicateur, appelé S80/S20, est utilisé par l’OFS et par Eurostat. Il est simple à comprendre, mais ne dit rien de ce qui se passe au milieu de la distribution.`) },

  { id: "in1-mediane", theme: "inegalites", niveau: 1, type: "calcul",
    titre: "Moyenne et médiane", competence: "Calculer une moyenne et une médiane.",
    gen: () => { const base = Array.from({ length: 6 }, () => rnd(42, 75) * 100); return { s: [...base, pick([18000, 22000, 25000, 30000])] }; },
    enonce: (p) => P("Voici les salaires mensuels bruts des sept employés d’une petite entreprise, dont le directeur (en francs) :", `<b>${p.s.map((x) => fmt(x)).join(" ; ")}</b>`, "Calculez le salaire moyen et le salaire médian (au franc près)."),
    champs: [{ label: "Moyenne", unite: "fr.", tol: 1 }, { label: "Médiane", unite: "fr.", tol: 1 }],
    reponses: (p) => [Math.round(p.s.reduce((a, b) => a + b, 0) / p.s.length), median(p.s)],
    indice: "Moyenne = somme ÷ nombre. Médiane : rangez les salaires dans l’ordre ; c’est celui du milieu (le 4e sur 7).",
    correction: (p) => { const s = [...p.s].sort((a, b) => a - b), m = p.s.reduce((a, b) => a + b, 0) / 7; return P(`Moyenne = ${fmt(p.s.reduce((a, b) => a + b, 0))} ÷ 7 ≈ <b>${fmt(Math.round(m))} francs</b>.`, `Dans l’ordre : ${s.map((x) => fmt(x)).join(" ; ")}. La médiane est le 4e : <b>${fmt(s[3])} francs</b>.`, "La moyenne est tirée vers le haut par le salaire très élevé du directeur ; la médiane, qui partage les salariés en deux moitiés, n’en dépend pas. C’est pourquoi on utilise surtout le salaire <b>médian</b> pour décrire la situation d’un salarié « typique ». En Suisse, il était de 7 024 francs bruts par mois en 2024 pour un plein temps (OFS)."); } },

  { id: "in1-vf-bases", theme: "inegalites", niveau: 1, type: "vf", notion: "courbe-kuznets",
    titre: "Mesurer les inégalités", competence: "Utiliser correctement les indicateurs d’inégalité.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Les inégalités de patrimoine sont en général plus faibles que les inégalités de revenus.", false, "C’est l’inverse : le patrimoine s’accumule et se transmet, il est beaucoup plus concentré que le revenu."],
      ["Si les 20 % les plus aisés et les 20 % les plus modestes ont le même revenu moyen, le rapport S80/S20 vaut 1.", true, "Le rapport S80/S20 divise le revenu moyen des plus aisés par celui des plus modestes. Il vaut 1 en cas d’égalité entre ces deux groupes et augmente avec l’écart."],
      ["Le revenu disponible est le revenu avant impôts et prestations sociales.", false, "Le revenu disponible est le revenu <b>après</b> impôts et cotisations, et après les prestations sociales reçues. C’est ce dont un ménage dispose réellement pour consommer et épargner."],
      ["La moitié des salariés gagnent plus que le salaire médian.", true, "C’est la définition de la médiane : elle partage la population en deux moitiés égales."]
    ] },

  { id: "in1-progressif", theme: "inegalites", niveau: 1, type: "qcm", notion: "r-g",
    titre: "Impôt progressif ou proportionnel ?", competence: "Distinguer les formes d’impôt.",
    enonce: P("Un impôt est dit progressif quand :"),
    options: ["Tout le monde paie le même montant.", "Tout le monde paie le même pourcentage de son revenu.", "Le pourcentage du revenu payé en impôt augmente avec le revenu.", "Les plus riches ne paient pas d’impôt."], c: 2, pourquoi: ["Un même montant pour tous est un impôt forfaitaire : en proportion, il pèse plus lourd sur les petits revenus.", "Un même pourcentage pour tous définit un impôt proportionnel.", null, "Un impôt progressif fait au contraire payer aux revenus élevés une part plus grande de leur revenu."],
    explication: P("Un impôt <b>progressif</b> prélève une part du revenu (taux moyen) d’autant plus grande que le revenu est élevé : c’est le cas de l’impôt fédéral direct et des impôts cantonaux sur le revenu en Suisse. Un impôt <b>proportionnel</b> prélève le même pourcentage pour tous ; un impôt <b>forfaitaire</b>, le même montant.", "Un impôt peut aussi être <b>régressif</b> : la TVA, qui frappe la consommation, pèse proportionnellement plus sur les ménages modestes, qui consomment une plus grande part de leur revenu.") },

  { id: "in1-pauvrete", theme: "inegalites", niveau: 1, type: "qcm", notion: "capabilites",
    titre: "Comment l’OFS mesure-t-il le risque de pauvreté ?", competence: "Distinguer deux façons de définir la pauvreté.",
    enonce: P("L’OFS mesure en Suisse un « taux de risque de pauvreté » : la part des personnes dont le revenu est inférieur à 60 % du revenu médian. De quel type de mesure s’agit-il ?"),
    options: ["D’une pauvreté absolue, le seuil correspondant à un panier de biens indispensables.", "D’une pauvreté relative, le seuil dépendant du niveau de vie habituel dans le pays.", "D’une mesure des inégalités de patrimoine entre les ménages.", "D’une pauvreté subjective, qui compte les personnes se disant pauvres dans une enquête."], c: 1, pourquoi: ["Le seuil est fixé à 60 % du revenu médian : il dépend du niveau de vie du pays, ce n’est pas un minimum fixe.", null, "La mesure porte sur le revenu, pas sur ce que les ménages possèdent.", "Le seuil est calculé à partir des revenus, pas de l’opinion des personnes sur leur situation."],
    explication: P("C’est une mesure de pauvreté <b>relative</b> : on est considéré comme à risque de pauvreté si l’on a beaucoup moins que la plupart des gens du même pays. Si tous les revenus doublaient, le taux ne changerait pas.", "La pauvreté <b>absolue</b>, elle, se définit par rapport à un minimum fixe, comme le seuil d’extrême pauvreté de la Banque mondiale, fixé à quelques dollars par jour (en parité de pouvoir d’achat). L’OFS publie aussi un taux de pauvreté fondé sur le minimum vital défini par les normes de l’aide sociale.") },

  { id: "in1-seuil", theme: "inegalites", niveau: 1, type: "calcul",
    titre: "Calculer un seuil de pauvreté", competence: "Appliquer la définition d’un seuil de pauvreté relatif.",
    gen: () => ({ med: rnd(38, 52) * 100 }),
    enonce: (p) => P(`Le revenu disponible médian d’une personne seule est de <b>${fmt(p.med)} francs</b> par mois.`, "Calculez le seuil de risque de pauvreté à 60 % du revenu médian, et le seuil plus strict à 50 %."),
    champs: [{ label: "Seuil à 60 %", unite: "fr.", tol: 1 }, { label: "Seuil à 50 %", unite: "fr.", tol: 1 }],
    reponses: (p) => [0.6 * p.med, 0.5 * p.med],
    indice: "Prendre 60 % d’un montant revient à le multiplier par un nombre décimal. Lequel ?",
    correction: (p) => P(`Seuil à 60 % : 0,6 × ${fmt(p.med)} ; seuil à 50 % : 0,5 × ${fmt(p.med)}.`, `Seuil à 60 % = <b>${fmt(0.6 * p.med)} francs</b> ; seuil à 50 % = <b>${fmt(0.5 * p.med)} francs</b>.`, "Les personnes dont le revenu est inférieur à ces seuils sont dites « à risque de pauvreté ». Le résultat dépend fortement du seuil choisi, et ne tient pas compte du patrimoine, ce qui peut compter beaucoup pour les retraités.") },

  { id: "in1-quintiles", theme: "inegalites", niveau: 1, type: "document",
    titre: "Comparer deux répartitions", competence: "Lire une répartition par quintiles.",
    enonce: P("Part du revenu total reçue par chaque cinquième de la population, du plus modeste au plus aisé, dans deux pays fictifs :") +
      `<table><thead><tr><th></th><th>1er quintile</th><th>2e</th><th>3e</th><th>4e</th><th>5e quintile</th></tr></thead><tbody><tr><td>Pays A</td><td>9 %</td><td>14 %</td><td>18 %</td><td>23 %</td><td>36 %</td></tr><tr><td>Pays B</td><td>4 %</td><td>9 %</td><td>14 %</td><td>21 %</td><td>52 %</td></tr></tbody></table>` +
      P("Quelle affirmation est correcte ?"),
    options: ["Le pays A est plus inégal, car son 3e quintile reçoit une part plus grande que celui du pays B.", "Le pays B est plus inégal : son quintile le plus aisé reçoit 52 % du revenu, contre 4 % pour le plus modeste.", "Les deux pays sont également inégaux, car dans chacun les parts totalisent 100 %.", "On ne peut pas comparer l’inégalité de ces deux pays sans connaître leur PIB respectif."], c: 1, pourquoi: ["Une part plus grande pour le quintile du milieu signale plutôt une répartition plus égale ; il faut surtout comparer les extrêmes.", null, "Les parts totalisent toujours 100 % : c’est leur répartition entre quintiles qui compte.", "Le PIB dit la taille du gâteau, pas la façon dont il est partagé ; les parts suffisent pour comparer les inégalités."],
    explication: P("Dans le pays B, le cinquième le plus aisé reçoit 52 % du revenu, soit 13 fois plus que le cinquième le plus modeste (52 ÷ 4). Dans le pays A, ce rapport n’est que de 4 (36 ÷ 9).", "Si l’on traçait les courbes de Lorenz, celle du pays B serait plus éloignée de la diagonale d’égalité, et son coefficient de Gini plus élevé.") },

  /* =========================== NIVEAU 2 : INTERMÉDIAIRE =========================== */
  { id: "in2-tranches", theme: "inegalites", niveau: 2, type: "calcul", notion: "r-g",
    titre: "Calculer un impôt par tranches", competence: "Appliquer un barème progressif et distinguer taux marginal et taux moyen.",
    gen: () => ({ r: pick([35000, 48000, 62000, 75000, 90000, 120000, 150000, 210000]) }),
    enonce: (p) => P("Un barème fictif d’impôt sur le revenu annuel : <b>0 %</b> jusqu’à 20 000 francs ; <b>10 %</b> sur la part de 20 000 à 50 000 ; <b>20 %</b> sur la part de 50 000 à 100 000 ; <b>30 %</b> sur la part au-delà de 100 000.", `Calculez l’impôt dû sur un revenu de <b>${fmt(p.r)} francs</b>, puis le taux moyen d’imposition (arrondi à une décimale), puis le taux marginal, celui qui frappe le dernier franc gagné.`),
    champs: [{ label: "Impôt", unite: "fr.", tol: 1 }, { label: "Taux moyen", unite: "%", tol: 0.1 }, { label: "Taux marginal", unite: "%", tol: 0.1 }],
    reponses: (p) => [impot(p.r), Math.round((impot(p.r) / p.r) * 1000) / 10, TR.find(([lim]) => p.r <= lim)[1] * 100],
    indice: "Chaque taux ne s’applique qu’à la part du revenu comprise dans sa tranche. Additionnez les montants, puis divisez par le revenu. Le taux marginal est celui de la tranche où se situe le revenu.",
    correction: (p) => { const parts = []; let prev = 0; for (const [lim, t] of TR) { if (p.r > prev && t > 0) parts.push(`${fmt(t * 100)} % × ${fmt(Math.min(p.r, lim) - prev)} = ${fmt((Math.min(p.r, lim) - prev) * t)}`); prev = lim; } const tm = TR.find(([lim]) => p.r <= lim)[1]; return P(`Par tranche : ${parts.join(" ; ")}.`, `Impôt total = <b>${fmt(impot(p.r))} francs</b> ; taux moyen = ${fmt(impot(p.r))} ÷ ${fmt(p.r)} ≈ <b>${fmt(100 * impot(p.r) / p.r, 1)} %</b>.`, `Le <b>taux marginal</b>, celui qui s’applique au dernier franc gagné, est de <b>${fmt(tm * 100)} %</b>, bien plus que le taux moyen. Gagner plus ne fait jamais payer le taux supérieur sur tout le revenu : c’est une idée fausse répandue.`); } },

  { id: "in2-gini", theme: "inegalites", niveau: 2, type: "calcul", notion: "courbe-kuznets",
    titre: "Calculer un coefficient de Gini", competence: "Appliquer la formule du Gini à une petite population.",
    gen: () => ({ x: Array.from({ length: 4 }, () => rnd(2, 12) * 10) }),
    enonce: (p) => P(`Quatre personnes ont les revenus suivants (en milliers de francs) : <b>${p.x.join(" ; ")}</b>.`, "Le coefficient de Gini peut se calculer ainsi. On additionne les écarts de revenu, en valeur absolue, entre chaque personne et chacune des trois autres. Chaque couple de personnes est donc compté deux fois, ce qui fait douze écarts. On divise cette somme par <b>2 × n² × revenu moyen</b>, avec n = 4. Calculez-le (arrondi à trois décimales)."),
    champs: [{ label: "Gini", unite: "", tol: 0.0015 }],
    reponses: (p) => { const n = p.x.length, mu = p.x.reduce((a, b) => a + b, 0) / n; let s = 0; for (const a of p.x) for (const b of p.x) s += Math.abs(a - b); return [Math.round((s / (2 * n * n * mu)) * 1000) / 1000]; },
    indice: "Commencez par les six couples possibles, additionnez leurs écarts, puis doublez la somme.",
    correction: (p) => { const n = p.x.length, mu = p.x.reduce((a, b) => a + b, 0) / n; let s = 0; for (const a of p.x) for (const b of p.x) s += Math.abs(a - b); const g = s / (2 * n * n * mu); const pairs = []; for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) pairs.push(`|${p.x[i]} − ${p.x[j]}| = ${Math.abs(p.x[i] - p.x[j])}`); return P(`Revenu moyen = ${p.x.join(" + ")} ÷ 4 = ${fmt(mu, 2)}.`, `Les six couples possibles donnent les écarts suivants : ${pairs.join(" ; ")}. Leur somme vaut ${fmt(s / 2)} ; on la double, car chaque couple compte deux fois : ${fmt(s)}.`, `G = ${fmt(s)} ÷ (2 × 16 × ${fmt(mu, 2)}) ≈ <b>${fmt(g, 3)}</b>.`, "Le Gini vaudrait 0 si tous avaient le même revenu. Ici, avec seulement quatre personnes, sa valeur maximale possible serait 0,75."); } },

  { id: "in2-kuznets", theme: "inegalites", niveau: 2, type: "qcm", notion: "courbe-kuznets",
    titre: "La courbe de Kuznets à l’épreuve", competence: "Connaître l’évolution des inégalités au XXe siècle et ce qu’elle dit de la courbe de Kuznets.",
    enonce: P("En 1955, Simon Kuznets suggère que les inégalités augmentent au début de l’industrialisation, puis diminuent avec le développement. Que montrent les séries reconstituées par Piketty, Saez et Atkinson pour les pays riches au XXe siècle ?"),
    options: ["Une baisse continue des inégalités, comme le prévoyait Kuznets.", "Une forte baisse entre 1914 et 1945, puis une remontée depuis 1980, soit une courbe en U.", "Une hausse continue des inégalités depuis 1900, dans tous les pays riches.", "Aucune variation notable des inégalités, qui seraient restées stables sur tout le siècle."], c: 1, pourquoi: ["Les inégalités remontent depuis 1980 dans la plupart des pays riches, surtout aux États-Unis : la baisse n’a pas continué.", null, "Les inégalités ont fortement baissé entre 1914 et 1945, avant de remonter : il n’y a pas de hausse continue.", "Les séries montrent de très fortes variations, avec une chute puis une remontée de la part des plus hauts revenus."],
    explication: P("Les séries fiscales montrent une <b>courbe en U</b> : très fortes avant 1914, les inégalités chutent avec les guerres, la crise de 1929, l’inflation et l’impôt progressif, restent faibles jusqu’aux années 1970, puis remontent depuis 1980, surtout aux États-Unis.", "La baisse observée par Kuznets, qui disposait de données jusqu’aux années 1950, n’était donc pas le résultat naturel du développement, mais en grande partie de chocs et de choix politiques. La remontée est forte dans les pays anglo-saxons, beaucoup plus modérée en Europe continentale et au Japon. En Suisse, selon Föllmi et Martínez, les inégalités de revenus ont moins varié au XXe siècle que dans les grands pays voisins.") },

  { id: "in2-redistribution", theme: "inegalites", niveau: 2, type: "calcul", notion: "r-g",
    titre: "L’effet de la redistribution", competence: "Mesurer l’effet des impôts et des transferts sur les inégalités.",
    gen: () => ({ r: rnd(140, 200) * 1000, p: rnd(18, 30) * 1000, ti: pick([0.25, 0.3, 0.35]), tr: rnd(10, 20) * 1000 }),
    enonce: (p) => P(`Avant impôts et transferts, le revenu moyen des 20 % les plus aisés est de <b>${fmt(p.r)} francs</b> par an, celui des 20 % les plus modestes de <b>${fmt(p.p)} francs</b>.`, `Les plus aisés paient en moyenne <b>${fmt(p.ti * 100)} %</b> de leur revenu en impôts et cotisations ; les plus modestes reçoivent en moyenne <b>${fmt(p.tr)} francs</b> de prestations sociales (on néglige leurs impôts).`, "Calculez le rapport S80/S20 avant, puis après redistribution (arrondis à une décimale)."),
    champs: [{ label: "Avant", unite: "", tol: 0.1 }, { label: "Après", unite: "", tol: 0.1 }],
    reponses: (p) => [Math.round((p.r / p.p) * 10) / 10, apres(p)],
    indice: "Après redistribution : revenu des plus aisés × (1 − taux) ; revenu des plus modestes + prestations.",
    correction: (p) => { const a = p.r / p.p, ra = p.r * (1 - p.ti), pa = p.p + p.tr, b = ra / pa; return P(`Avant : ${fmt(p.r)} ÷ ${fmt(p.p)} ≈ <b>${fmt(a, 1)}</b>.`, `Après : ${fmt(ra)} ÷ ${fmt(pa)} ≈ <b>${fmt(apres(p), 1)}</b>.`, `La redistribution réduit le rapport d’environ ${fmt(100 * (1 - b / a), 0)} %. Dans tous les pays riches, les impôts et les transferts réduisent nettement les inégalités de revenus ; l’ampleur de cette réduction varie beaucoup d’un pays à l’autre.`); } },

  { id: "in2-vf-justice", theme: "inegalites", niveau: 2, type: "vf", notion: "capabilites",
    titre: "Les théories de la justice", competence: "Associer chaque auteur à sa conception de la justice.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Pour Hayek, la « justice sociale » est un objectif central de l’économie de marché.", false, "Pour Hayek, la répartition issue du marché ne résulte de l’intention de personne : parler de justice à son propos n’a pas de sens, et vouloir la corriger menace la liberté."],
      ["Pour Amartya Sen, il suffit d’égaliser les revenus pour égaliser les libertés réelles.", false, "Sen rappelle que des personnes au même revenu n’ont pas les mêmes possibilités : une personne malade ou handicapée a besoin de plus de ressources. Il propose d’égaliser les <b>capabilités</b>."],
      ["Pour John Rawls, les inégalités ne sont justes que si elles profitent aux plus défavorisés.", true, "C’est son « principe de différence », choisi derrière un « voile d’ignorance », sans savoir quelle place on occupera dans la société."],
      ["Pour Robert Nozick, une répartition est juste si elle résulte d’échanges libres à partir de possessions acquises légitimement.", true, "Il juge la justice aux procédures et aux droits, pas aux résultats."]
    ] },

  { id: "in2-pareto", theme: "inegalites", niveau: 2, type: "qcm", notion: "optimum-pareto",
    titre: "Efficace mais injuste ?", competence: "Comprendre la portée et les limites de l’optimum de Pareto.",
    enonce: P("Une situation est un optimum de Pareto si l’on ne peut améliorer la situation de quelqu’un sans détériorer celle d’un autre. Une répartition où une personne possède tout et les autres rien peut-elle être un optimum de Pareto ?"),
    options: ["Non, car une répartition aussi inégale est forcément injuste, donc jamais efficace.", "Seulement si la personne a obtenu ces biens par son travail et non par héritage.", "Non, car l’optimum de Pareto impose une répartition égale entre tous.", "Oui : on ne peut rien enlever à cette personne sans détériorer sa situation."], c: 3, pourquoi: ["Le critère de Pareto ne juge pas la justice : une répartition peut être injuste et pourtant efficace au sens de Pareto.", "Le critère ne s’intéresse pas à l’origine des biens : seule compte la possibilité d’améliorer le sort de quelqu’un sans nuire à personne.", "Il existe une infinité d’optimums de Pareto, égalitaires ou non : le critère n’impose aucune répartition.", null],
    explication: P("L’<b>optimum de Pareto</b> est un critère d’<b>efficacité</b> : il dit qu’on ne gaspille pas de possibilités d’améliorer le sort de quelqu’un sans nuire à personne. Il existe une infinité d’optimums, des plus égalitaires aux plus inégalitaires.", "Choisir entre eux suppose un jugement d’<b>équité</b>, que le critère de Pareto ne fournit pas. C’est pourquoi l’économie du bien-être a dû faire appel à la philosophie, de Rawls à Sen.") },

  { id: "in2-successions", theme: "inegalites", niveau: 2, type: "redaction", notion: "r-g",
    titre: "Faut-il taxer davantage les grands héritages ?", competence: "Argumenter sur une question fiscale.",
    enonce: P("En Suisse, les successions transmises aux enfants sont exonérées d’impôt dans la plupart des cantons. Le 30 novembre 2025, une initiative qui proposait de taxer à 50 % la part des successions et des donations dépassant 50 millions de francs, pour financer la politique climatique, a été rejetée par près de 80 % des votants.", "<b>Consigne :</b> présentez des arguments pour et contre une imposition plus forte des grands héritages, en utilisant au moins une notion d’économie, puis concluez. Tenez compte du contexte suisse. Longueur attendue, 10 à 15 lignes."),
    criteres: ["La réponse présente au moins deux arguments pour : égalité des chances, concentration du patrimoine, poids de l’héritage (r > g), mérite, recettes publiques, efficacité relative de cet impôt…", "Elle présente au moins deux arguments contre : risque de départ des grandes fortunes, transmission des entreprises familiales, double imposition, liberté de transmettre, concurrence fiscale entre pays et cantons…", "Elle nomme au moins une notion d’économie et l’explique en une phrase (par exemple, quand r dépasse g, les patrimoines hérités pèsent de plus en plus lourd).", "Elle tient compte du résultat de la votation de 2025 ou du contexte suisse (cantons, impôt sur la fortune).", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Pour :</b> l’héritage transmet des inégalités qui ne correspondent à aucun mérite ; taxer les très grandes successions favorise l’<b>égalité des chances</b>. Selon Piketty, quand le rendement du capital dépasse la croissance (<b>r > g</b>), le poids des patrimoines hérités augmente : l’impôt sur les successions en limite la concentration. Beaucoup d’économistes jugent aussi cet impôt moins nuisible à l’activité que les impôts sur le travail.", "<b>Contre :</b> les grandes fortunes sont mobiles ; un taux très élevé peut les inciter à quitter la Suisse, et la recette attendue peut alors baisser. La transmission des entreprises familiales peut être menacée si les héritiers doivent vendre pour payer l’impôt. Certains y voient aussi une double imposition d’un patrimoine déjà imposé chaque année par l’impôt cantonal sur la fortune.", "<b>Conclusion :</b> le rejet massif de 2025 montre que la proposition, avec son taux de 50 %, n’a pas convaincu. La crainte d’un départ des grandes fortunes et d’une fragilisation des entreprises familiales a dominé la campagne. Un impôt modéré, avec des règles pour les entreprises familiales et une coordination entre pays, est souvent présenté comme un compromis plus réaliste.") },

  { id: "in2-gatsby", theme: "inegalites", niveau: 2, type: "qcm", notion: "capabilites",
    titre: "Inégalités et mobilité sociale", competence: "Relier inégalités et égalité des chances.",
    enonce: P("L’économiste Miles Corak a mis en évidence la « courbe de Gatsby le Magnifique ». Que montre-t-elle ?"),
    options: ["Que les pays les plus inégaux sont aussi ceux où la mobilité sociale est la plus forte.", "Que la mobilité sociale est la même dans tous les pays, quel que soit leur niveau d’inégalité.", "Que les inégalités n’ont aucun lien avec la mobilité sociale d’un pays à l’autre.", "Que plus un pays est inégal, plus le revenu des enfants dépend de celui de leurs parents."], c: 3, pourquoi: ["C’est l’inverse : les pays les plus inégaux, comme les États-Unis, ont la mobilité sociale la plus faible.", "La mobilité varie fortement : elle est beaucoup plus élevée dans les pays nordiques qu’aux États-Unis ou au Royaume-Uni.", "La courbe montre justement une relation nette : plus les inégalités sont fortes, plus la mobilité est faible.", null],
    explication: P("Les pays où les inégalités de revenus sont fortes, comme les États-Unis ou le Royaume-Uni, sont aussi ceux où le revenu des enfants est le plus lié à celui de leurs parents. Les pays nordiques combinent faibles inégalités et forte mobilité.", "Cette relation suggère que les inégalités de résultats d’une génération deviennent des inégalités de chances pour la suivante, par l’éducation, les réseaux et l’héritage. Elle ne prouve pas à elle seule un lien de cause à effet.") },

  /* =========================== NIVEAU 3 : AVANCÉ =========================== */
  { id: "in3-rg", theme: "inegalites", niveau: 3, type: "calcul", notion: "r-g",
    titre: "Ce que r > g signifie vraiment", competence: "Mesurer l’effet de r > g sur la concentration d’une fortune : capitalisation et temps de doublement de l’écart.",
    gen: () => ({ g: pick([1.5, 2]), r: pick([3, 4, 5]), h: pick([10, 20, 40]), n: pick([20, 30]) }),
    enonce: (p) => P(`Selon Thomas Piketty, quand le rendement du capital r dépasse la croissance g, les grandes fortunes s’éloignent du revenu moyen. Un héritier possède une fortune égale à <b>${p.h} fois</b> le revenu moyen. Il réinvestit chaque année tout le rendement de sa fortune, <b>r = ${fmt(p.r)} %</b>, tandis que le revenu moyen croît de <b>${fmt(p.g)} %</b> par an.`, `1. Combien de fois le revenu moyen sa fortune vaudra-t-elle dans <b>${p.n} ans</b> ? Arrondissez à l’unité.`, "2. En combien d’années le rapport entre sa fortune et le revenu moyen double-t-il ? Arrondissez à l’unité."),
    champs: [{ label: "Fortune de l’héritier", unite: "fois le revenu moyen", tol: 2 }, { label: "Temps de doublement du rapport", unite: "ans", tol: 1.5 }],
    reponses: (p) => { const q = (1 + p.r / 100) / (1 + p.g / 100); return [X.arr(p.h * Math.pow(q, p.n), 0), X.arr(Math.log(2) / Math.log(q), 0)]; },
    indice: "Chaque année, le rapport fortune ÷ revenu moyen est multiplié par un même facteur. Pour le doublement, cherchez l’exposant n pour lequel ce facteur, élevé à la puissance n, vaut 2.",
    correction: (p) => { const q = (1 + p.r / 100) / (1 + p.g / 100), v = p.h * Math.pow(q, p.n), t = Math.log(2) / Math.log(q); return P(`1. La fortune croît de ${fmt(p.r)} % par an, le revenu moyen de ${fmt(p.g)} %. Rapportée au revenu moyen, elle est donc multipliée chaque année par q = ${fmt(1 + p.r / 100, 3)} ÷ ${fmt(1 + p.g / 100, 3)} ≈ ${fmt(q, 4)}. Après ${p.n} ans, ${p.h} × ${fmt(q, 4)}<sup>${p.n}</sup> ≈ <b>${fmt(v, 0)} fois</b> le revenu moyen.`, `2. On cherche n tel que q<sup>n</sup> = 2, soit n = ln 2 ÷ ln q. Avec ln q ≈ ${fmt(Math.log(q), 4)}, on obtient n ≈ <b>${fmt(t, 0)} ans</b>.`, `Le temps de doublement ne dépend ni de la fortune de départ ni du nombre d’années du premier calcul. Il ne dépend que de r et de g, et pour l’essentiel de l’écart r − g, ici ${fmt(p.r - p.g, 1)} point${p.r - p.g >= 2 ? "s" : ""}. Plus cet écart est faible, plus le doublement est lent.`, "C’est là que joue r > g : la fortune de celui qui réinvestit son rendement s’éloigne du revenu moyen. Chez Piketty, cette inégalité explique la concentration des patrimoines entre les personnes, pas une explosion du patrimoine total.", "Ce calcul est très simplifié : l’héritier ne consomme rien, ne paie pas d’impôt et ne partage pas sa fortune entre plusieurs enfants. Avec un impôt annuel sur le rendement, r diminue et le temps de doublement s’allonge."); } },

  { id: "in3-top", theme: "inegalites", niveau: 3, type: "calcul", notion: "r-g",
    titre: "Le sommet de la distribution : une loi de Pareto", competence: "Établir un coefficient de Pareto à partir de deux seuils de revenu et en déduire la part des plus riches.",
    gen: () => { const a0 = pick([1.5, 1.7, 2, 2.5]), s1 = rnd(12, 18) * 10000, s2 = Math.round(s1 * Math.pow(10, 1 / a0) / 10000) * 10000, s2b = Math.round(s2 * pick([0.85, 1.2]) / 10000) * 10000; return { s1, s2, s2b }; },
    enonce: (p) => P(`Dans un pays, <b>10 %</b> des contribuables ont un revenu annuel supérieur à <b>${fmt(p.s1)} francs</b> et <b>1 %</b> un revenu supérieur à <b>${fmt(p.s2)} francs</b>.`, "Au sommet de la distribution, la part des contribuables dont le revenu dépasse un seuil y diminue comme y<sup>−α</sup>. C’est une loi de Pareto, dont α est le coefficient. Plus α est faible, plus la queue de la distribution est épaisse.", "1. Établissez le coefficient α à partir des deux seuils (arrondi à deux décimales).", "2. Dans le modèle de Pareto, la part du revenu total reçue par les p % les plus aisés vaut p<sup>1 − 1/α</sup>, avec p en fraction. Calculez la part du revenu total des 1 % les plus aisés (arrondie à une décimale).", `3. Dans un second pays, le seuil des 10 % est le même, mais celui des 1 % est de <b>${fmt(p.s2b)} francs</b>. Son sommet est-il plus ou moins concentré que celui du premier pays ?`),
    champs: [{ label: "Coefficient α", unite: "", tol: 0.02 }, { label: "Part du revenu des 1 % les plus aisés", unite: "%", tol: 0.4 }, { label: "Le sommet du second pays est", choix: ["plus concentré", "moins concentré"] }],
    reponses: (p) => { const a = Math.log(10) / Math.log(p.s2 / p.s1); return [X.arr(a, 2), X.arr(100 * Math.pow(0.01, 1 - 1 / a), 1), p.s2b > p.s2 ? 0 : 1]; },
    indice: "Quand on passe de S1 à S2, la part des contribuables au-dessus du seuil est divisée par 10. Écrivez cette égalité avec la loi de Pareto, puis résolvez-la avec un logarithme.",
    correction: (p) => { const x = p.s2 / p.s1, a = Math.log(10) / Math.log(x), e = 1 - 1 / a, part = 100 * Math.pow(0.01, e), a2 = Math.log(10) / Math.log(p.s2b / p.s1), plus = p.s2b > p.s2; return P(`1. Le seuil est multiplié par x = ${fmt(p.s2)} ÷ ${fmt(p.s1)} ≈ ${fmt(x, 3)}, et la part des contribuables au-dessus est divisée par 10. La loi de Pareto donne x<sup>α</sup> = 10, donc α = ln 10 ÷ ln x, avec ln 10 ≈ ${fmt(Math.log(10), 3)} et ln x ≈ ${fmt(Math.log(x), 3)}. On obtient α ≈ <b>${fmt(a, 2)}</b>.`, `2. Exposant : 1 − 1 ÷ ${fmt(a, 3)} ≈ ${fmt(e, 4)}. La part vaut alors 0,01<sup>${fmt(e, 4)}</sup>, soit environ <b>${fmt(part, 1)} %</b> du revenu total pour 1 % des contribuables.`, `3. Pour le second pays, x = ${fmt(p.s2b)} ÷ ${fmt(p.s1)} ≈ ${fmt(p.s2b / p.s1, 3)}, d’où α ≈ ${fmt(a2, 2)}. Son coefficient est ${plus ? "plus faible" : "plus élevé"}, sa queue de distribution est ${plus ? "plus épaisse" : "plus mince"} et son sommet est <b>${plus ? "plus concentré" : "moins concentré"}</b>.`, "Le coefficient de Pareto est lié au paramètre a = α ÷ (α − 1) de la formule d’imposition optimale de Diamond et Saez. Le modèle est une approximation : les revenus réels ne suivent une loi de Pareto qu’au sommet, et les données fiscales servent à estimer α. Piketty et Saez s’intéressent à ces parts du sommet, que les enquêtes classiques mesurent mal."); } },

  { id: "in3-marginal-effectif", theme: "inegalites", niveau: 3, type: "calcul",
    titre: "Le taux marginal effectif et la trappe à pauvreté", competence: "Calculer ce que rapporte réellement un revenu supplémentaire, effet de seuil compris.",
    gen: () => { let q; do { q = { gain: pick([400, 500, 600, 800]), aide: pick([0.2, 0.3, 0.4]), imp: pick([0.1, 0.15]), forfait: pick([150, 250, 350, 450]) }; } while (Math.abs(q.gain * (1 - q.aide - q.imp) - q.forfait) < 30); return q; },
    enonce: (p) => P(`Une mère seule augmente son salaire de <b>${fmt(p.gain)} francs</b> par mois. Cette hausse a trois effets. Les aides au logement et à l’assurance maladie diminuent de <b>${fmt(p.aide * 100)} %</b> du gain. Elle paie <b>${fmt(p.imp * 100)} %</b> du gain en impôts et cotisations supplémentaires. Enfin, son nouveau salaire dépasse un seuil au-delà duquel elle perd un subside forfaitaire de <b>${fmt(p.forfait)} francs</b> par mois.`, "Calculez son gain réel mensuel, avec son signe s’il est négatif, et son taux marginal effectif de prélèvement, c’est-à-dire la part du gain brut qui lui est retirée. Arrondissez à l’unité. Dites ensuite si cette augmentation lui est profitable."),
    champs: [{ label: "Gain réel", unite: "fr.", tol: 1 }, { label: "Taux marginal effectif", unite: "%", tol: 1 }, { label: "Cette augmentation lui est-elle profitable ?", choix: ["oui", "non"] }],
    reponses: (p) => { const net = p.gain * (1 - p.aide - p.imp) - p.forfait; return [X.arr(net, 0), X.arr(((p.aide + p.imp) * p.gain + p.forfait) / p.gain * 100, 0), net > 0 ? 0 : 1]; },
    indice: "Retirez du gain brut les aides perdues, les impôts supplémentaires et le subside forfaitaire. Le taux marginal effectif rapporte tout ce qui est retiré au gain brut.",
    correction: (p) => { const aide = p.aide * p.gain, imp = p.imp * p.gain, net = p.gain - aide - imp - p.forfait, taux = (aide + imp + p.forfait) / p.gain * 100; return P(`Aides dégressives perdues : ${fmt(aide)} francs ; impôts et cotisations : ${fmt(imp)} francs ; subside forfaitaire perdu : ${fmt(p.forfait)} francs.`, `Gain réel = ${fmt(p.gain)} − ${fmt(aide)} − ${fmt(imp)} − ${fmt(p.forfait)} = <b>${fmt(X.arr(net, 0))} francs</b>. Taux marginal effectif = ${fmt(aide + imp + p.forfait)} ÷ ${fmt(p.gain)} ≈ <b>${fmt(X.arr(taux, 0))} %</b>.`, net > 0 ? `Le gain réel est positif : l’augmentation <b>est profitable</b>, mais sur ${fmt(p.gain)} francs gagnés en plus, il n’en reste que ${fmt(X.arr(net, 0))}.` : "Le gain réel est négatif : l’augmentation <b>n’est pas profitable</b>. Le taux marginal effectif dépasse 100 %, et la mère est plus pauvre après avoir augmenté son salaire.", "C’est la <b>trappe à pauvreté</b> : quand le cumul des aides dégressives et des effets de seuil retire presque tout le gain, travailler davantage rapporte peu, voire fait perdre de l’argent. Plusieurs cantons ont réformé leurs barèmes pour lisser ces seuils, ce qui coûte plus cher en prestations mais rend l’emploi plus rentable."); } },

  { id: "in3-elephant", theme: "inegalites", niveau: 3, type: "qcm", notion: "courbe-kuznets",
    titre: "La courbe de l’éléphant", competence: "Décomposer l’inégalité mondiale en une part entre pays et une part à l’intérieur des pays.",
    enonce: P("Branko Milanović décompose l’inégalité mondiale des revenus en deux parts, l’une entre les pays, l’autre à l’intérieur de chaque pays. Entre 1988 et 2008, les classes moyennes de la Chine et de l’Inde rattrapent en partie les revenus des pays riches. Dans ces pays riches, les classes moyennes et populaires stagnent, alors que le 1 % le plus riche voit son revenu croître fortement. La courbe qui rapporte la croissance du revenu à la position dans la distribution mondiale a la forme d’un éléphant.", "Que peut-on en déduire pour l’évolution des deux parts ?"),
    options: ["Les deux parts reculent, puisque les classes moyennes de la Chine et de l’Inde rattrapent peu à peu les pays riches.", "Les deux parts progressent, puisque les plus riches des pays riches voient leur revenu croître plus vite que les autres.", "Entre pays, l’écart recule ; dans les pays riches, il progresse ; au total, l’inégalité mondiale peut reculer.", "L’inégalité mondiale est la simple moyenne des inégalités nationales, donc elle suit la hausse observée dans les pays riches."], c: 2, pourquoi: ["Le rattrapage réduit l’écart entre pays, mais la stagnation des classes moyennes et la hausse du sommet augmentent l’inégalité à l’intérieur des pays riches.", "Entre pays, l’écart a reculé : les revenus moyens de la Chine et de l’Inde se sont rapprochés de ceux des pays riches.", null, "L’inégalité mondiale ne se calcule pas en faisant la moyenne des inégalités nationales : elle compte aussi les écarts entre pays. Ici, les deux parts ont évolué en sens inverse."],
    explication: P("La « bosse » de l’éléphant correspond aux classes moyennes de Chine, d’Inde et d’autres pays émergents, dont les revenus ont fortement augmenté. La « trompe » levée, aux 1 % les plus riches du monde. Le creux correspond aux classes moyennes et populaires des pays riches, dont les revenus ont stagné.", "Les inégalités <b>entre pays</b> ont donc diminué, alors que les inégalités <b>à l’intérieur</b> de nombreux pays ont augmenté. Les deux mouvements jouent en sens contraire sur l’inégalité mondiale, ce qui explique qu’elle ait peu varié sur la période. Cette évolution aide à comprendre le malaise d’une partie des classes moyennes occidentales face à la mondialisation.") },

  { id: "in3-vf-piketty", theme: "inegalites", niveau: 3, type: "vf", notion: "r-g",
    titre: "Débats autour de Piketty", competence: "Prévoir ce qu’impliquent la thèse de Piketty et ses critiques dans des cas précis.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Matthew Rognlie a montré qu’une grande partie de la hausse de la part du capital depuis 1950 vient du logement.", true, "Selon ses calculs, la hausse de la part nette du capital dans le revenu depuis l’après-guerre vient presque entièrement du logement, et non du capital productif des entreprises."],
      ["Avec un taux d’épargne nette de 10 % et une croissance de 2 %, le patrimoine d’un pays tend vers cinq années de revenu national. Si la croissance tombe à 1 %, il tend vers dix années.", true, "Le patrimoine rapporté au revenu national tend vers β = s ÷ g, soit 10 ÷ 2 = 5, puis 10 ÷ 1 = 10. Une croissance plus faible élève donc ce rapport, à condition que le taux d’épargne reste le même, hypothèse que critiquent Krusell et Smith."],
      ["Un héritier qui consomme chaque année tout le rendement de sa fortune la voit diminuer par rapport au revenu moyen quand celui-ci croît, même si r dépasse g.", true, "Sa fortune reste constante en valeur, alors que le revenu moyen augmente : rapportée à ce revenu, elle baisse. L’écart r > g ne creuse la distance que pour celui qui réinvestit son rendement."],
      ["Selon Acemoglu et Robinson, dès que r dépasse g, les inégalités d’un pays augmentent inévitablement, quelles que soient ses institutions.", false, "Ils contestent l’idée de « lois générales du capitalisme ». Pour eux, le sort des inégalités dépend d’abord des institutions politiques, qui peuvent canaliser ou laisser jouer les forces du marché."]
    ] },

  { id: "in3-ecart-salarial", theme: "inegalites", niveau: 3, type: "calcul",
    titre: "L’écart salarial entre femmes et hommes", competence: "Décomposer un écart salarial en une part expliquée par deux facteurs et une part inexpliquée.",
    gen: () => { let q; do { const h = rnd(68, 80) * 100, ecart = pick([10, 12, 14, 16, 18]); q = { h, f: Math.round(h * (1 - ecart / 100)), b: pick([80, 100, 120]), de: pick([2, 3, 4]), prime: pick([2000, 2500, 3000]), dc: pick([8, 10, 12, 15]) }; const r = (q.b * q.de + q.prime * q.dc / 100) / (q.h - q.f); if (r < 0.3 || r > 0.75) q = null; } while (!q); return q; },
    enonce: (p) => P(`Dans une branche, le salaire mensuel moyen est de <b>${fmt(p.h)} francs</b> pour les hommes et de <b>${fmt(p.f)} francs</b> pour les femmes.`, `Une analyse à la manière d’Oaxaca et Blinder retient deux facteurs. Les femmes ont en moyenne <b>${p.de} ans</b> d’expérience de moins que les hommes, et chaque année d’expérience est payée <b>${fmt(p.b)} francs</b> de plus par mois. Elles sont aussi moins souvent cadres, de <b>${p.dc} points de pourcentage</b>, et un poste de cadre rapporte <b>${fmt(p.prime)} francs</b> de plus par mois.`, "Calculez l’écart salarial en % du salaire des hommes (arrondi à une décimale), la part de l’écart que ces deux facteurs expliquent (en francs par mois), puis la part inexpliquée en % de l’écart total (arrondie à l’unité)."),
    champs: [{ label: "Écart salarial", unite: "%", tol: 0.1 }, { label: "Part expliquée", unite: "fr.", tol: 1 }, { label: "Part inexpliquée", unite: "% de l’écart", tol: 0.5 }],
    reponses: (p) => { const d = p.h - p.f, ex = p.b * p.de + p.prime * p.dc / 100; return [X.arr(d / p.h * 100, 1), X.arr(ex, 0), X.arr((d - ex) / d * 100, 0)]; },
    indice: "Pour chaque facteur, multipliez l’avantage moyen des hommes par ce que rapporte ce facteur. La part inexpliquée est ce qui reste de l’écart une fois la part expliquée retirée.",
    correction: (p) => { const d = p.h - p.f, e1 = p.b * p.de, e2 = p.prime * p.dc / 100, ex = e1 + e2; return P(`Écart en francs : ${fmt(p.h)} − ${fmt(p.f)} = ${fmt(d)} ; en % : ${fmt(d)} ÷ ${fmt(p.h)} × 100 ≈ <b>${fmt(100 * d / p.h, 1)} %</b>.`, `Expérience : ${p.de} × ${fmt(p.b)} = ${fmt(e1)} francs. Poste de cadre : ${fmt(p.prime)} × ${p.dc} % = ${fmt(e2)} francs. Part expliquée = ${fmt(e1)} + ${fmt(e2)} = <b>${fmt(ex)} francs</b> par mois.`, `Part inexpliquée : (${fmt(d)} − ${fmt(ex)}) ÷ ${fmt(d)} = ${fmt(d - ex)} ÷ ${fmt(d)} ≈ <b>${fmt(X.arr(100 * (d - ex) / d, 0))} %</b> de l’écart.`, "En Suisse, l’OFS mesure, selon ses enquêtes récentes, un écart salarial moyen de l’ordre de 15 à 18 % dans le secteur privé, dont près de la moitié n’est pas expliquée par les caractéristiques observées. La méthode utilisée est la décomposition d’Oaxaca et Blinder.", "Son interprétation se discute dans les deux sens. La part inexpliquée peut contenir autre chose que de la discrimination, par exemple une expérience mal mesurée, et la part expliquée peut elle-même refléter des inégalités, quand les femmes accèdent moins aux postes et aux branches les mieux payés.", "Depuis 2020, les entreprises de 100 employés et plus doivent analyser l’égalité salariale."); } },

  { id: "in3-rbi", theme: "inegalites", niveau: 3, type: "redaction", notion: "capabilites",
    titre: "Un revenu de base inconditionnel ?", competence: "Comparer des écoles sur une réforme de la protection sociale et dire sur quelle hypothèse elles s’opposent.",
    enonce: P("Le 5 juin 2016, les Suisses ont rejeté à près de 77 % une initiative pour un « revenu de base inconditionnel », qui proposait de verser à chaque habitant un revenu permettant de vivre dignement, sans condition. L’idée revient régulièrement dans le débat, notamment face à l’automatisation.", "<b>Consigne :</b> faut-il instaurer un revenu de base inconditionnel ? Présentez les arguments pour et contre, en mobilisant au moins une notion d’économie. Rattachez chaque position à une école ou à un auteur (par exemple Friedman et l’impôt négatif, Van Parijs et la liberté réelle, Rawls et la réciprocité, Sen et les capabilités), et dites sur quelle hypothèse ils s’opposent. Citez au moins une expérience ou une solution de rechange, puis concluez. Longueur attendue, 15 à 25 lignes."),
    criteres: ["La réponse présente au moins deux arguments pour : lutte contre la pauvreté, simplification des aides, suppression des trappes à pauvreté, liberté de choix (capabilités), réponse à l’automatisation, reconnaissance du travail non rémunéré…", "Elle présente au moins deux arguments contre : coût très élevé, hausse des impôts nécessaire, risque de baisse de l’offre de travail, montant insuffisant pour certains besoins, attractivité pour l’immigration, question de justice (« payer ceux qui ne travaillent pas »)…", "Elle mobilise au moins une notion : incitations, taux marginal effectif, trappe à pauvreté, capabilités, financement par l’impôt…", "La réponse nomme au moins deux écoles ou auteurs et l’hypothèse qui les sépare.", "Elle évoque des expériences ou alternatives : votation de 2016, expérience finlandaise, impôt négatif de Friedman, aides ciblées…", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Pour :</b> un revenu de base garantit à chacun un minimum, sans démarches ni contrôles humiliants. Il supprime les <b>trappes à pauvreté</b>, car on ne le perd pas en travaillant plus. Il élargit les <b>capabilités</b> au sens de Sen : se former, s’occuper de ses proches, s’engager bénévolement. Certains y voient une réponse à l’automatisation.", "<b>Contre :</b> verser un revenu suffisant à toute la population coûterait très cher et exigerait de fortes hausses d’impôts. Une partie des bénéficiaires pourrait réduire son temps de travail. Un montant identique pour tous ne couvre pas les besoins particuliers, liés au handicap ou au coût du logement, et l’idée de payer sans contrepartie heurte le sens de la réciprocité de beaucoup de citoyens. L’expérience finlandaise de 2017-2018 a montré une amélioration du bien-être, mais peu d’effet sur l’emploi.", "<b>Écoles et hypothèses.</b> Milton Friedman défendait un impôt négatif, qui verse un complément aux bas revenus et le réduit progressivement quand le revenu monte. Il raisonne en économiste néoclassique : chacun répond aux incitations, et le retrait doit rester inférieur à 100 % pour que travailler rapporte toujours. Philippe Van Parijs défend un revenu versé à tous sans condition, au nom de la liberté réelle de chacun de choisir sa vie. Rawls, lui, juge que ceux qui choisissent de ne pas travailler ne doivent pas être soutenus par les autres, au nom de la réciprocité. Van Parijs et Rawls s’opposent donc sur ce que la société doit à celui qui refuse un emploi. Friedman et Van Parijs s’opposent sur le rôle de la condition : le premier garde un lien avec le revenu gagné pour préserver les incitations, le second le supprime. Sen, enfin, objecte qu’un montant uniforme n’égalise pas les libertés, puisque les besoins diffèrent d’une personne à l’autre.", "<b>Conclusion :</b> le rejet de 2016 montre la force de ces objections en Suisse. Des réformes plus ciblées, comme la simplification des aides et la réduction des effets de seuil, peuvent reprendre certains avantages du revenu de base à un coût plus faible.") },

  { id: "in3-capabilites", theme: "inegalites", niveau: 3, type: "document", notion: "capabilites",
    titre: "Même revenu, mêmes libertés ?", competence: "Appliquer l’approche par les capabilités à deux situations et choisir la politique qui les égalise.",
    enonce: P("Deux personnes ont exactement le même revenu disponible, 4 200 francs par mois :") +
      `<table><thead><tr><th></th><th>Anna</th><th>Bruno</th></tr></thead><tbody><tr><td>Santé</td><td>bonne</td><td>se déplace en fauteuil roulant</td></tr><tr><td>Logement</td><td>en ville, proche des transports</td><td>dans une vallée, sans transports adaptés</td></tr><tr><td>Soins à domicile à sa charge</td><td>0 franc par mois</td><td>650 francs par mois</td></tr><tr><td>Transport adapté (taxi)</td><td>0 franc par mois</td><td>450 francs par mois</td></tr></tbody></table><p class="ex-source">Situation inventée pour l’exercice : deux personnes fictives.</p>` +
      P("Calculez d’abord ce qu’il reste à Bruno pour vivre une fois ces deux dépenses payées. Quelle mesure, selon Amartya Sen, rapproche le mieux leurs libertés réelles ?"),
    options: ["Une prise en charge des 1 100 francs de soins et de transport de Bruno, qui lui rend un revenu utilisable de 4 200 francs.", "Aucune aide, puisque leurs revenus sont déjà égaux et qu’une aide à Bruno créerait une nouvelle inégalité.", "Une hausse de 1 100 francs du revenu des deux personnes, pour conserver l’égalité de leurs revenus.", "Une baisse du revenu d’Anna de 1 100 francs, pour ramener les deux revenus au même niveau réel."], c: 0, pourquoi: [null, "C’est la position que Sen critique. À revenu égal, Bruno ne dispose en réalité que de 3 100 francs après ses dépenses de santé et de transport, et ne peut pas faire les mêmes choses qu’Anna.", "Une hausse identique pour les deux maintient l’écart : Bruno resterait 1 100 francs en dessous d’Anna une fois ses dépenses payées. L’égalité des revenus n’est pas l’égalité des libertés.", "Enlever à Anna ne donne à Bruno aucune possibilité de plus. Pour Sen, l’objectif est d’élargir les libertés réelles de Bruno, pas de réduire celles d’Anna."],
    explication: P("Après ses soins (650 francs) et son transport adapté (450 francs), il reste à Bruno 4 200 − 650 − 450 = <b>3 100 francs</b> pour tout le reste, contre 4 200 francs à Anna. À revenu égal, ses possibilités réelles sont plus faibles.", "Pour Sen, le revenu n’est qu’un moyen. Ce qui compte, ce sont les <b>capabilités</b> : les possibilités réelles de mener la vie qu’on a des raisons de valoriser, comme se déplacer, travailler ou participer à la vie sociale. La capacité de transformer un revenu en libertés varie d’une personne à l’autre, ce qu’on appelle un <b>facteur de conversion</b>.", "C’est pourquoi l’égalité des revenus ne suffit pas. Une aide ciblée sur ce qui handicape Bruno, soins ou accessibilité des transports, élargit ses capabilités bien plus qu’une hausse uniforme des revenus.") },
  { id: "in1-fait-valeur", theme: "inegalites", niveau: 1, type: "vf", typeLib: "Constat ou jugement de valeur", etiquettes: ["Constat", "Jugement de valeur"],
    titre: "Constat ou jugement de valeur ?", competence: "Distinguer un constat, que l’on peut vérifier, d’un jugement de valeur, qui dit ce qui devrait être.",
    enonce: P("Pour chaque affirmation, dites s’il s’agit d’un <b>constat</b>, que l’on peut vérifier avec des données, même s’il se révèle faux, ou d’un <b>jugement de valeur</b>, qui dit ce qui devrait être."),
    affirmations: [
      ["Un héritage de plusieurs millions est moins légitime qu’un revenu gagné par le travail.", false, "Il exprime une appréciation sur ce qui est légitime. Des faits peuvent éclairer le débat, mais pas le trancher, même sans le mot « devraient »."],
      ["En Suisse, la fortune est plus inégalement répartie que les revenus.", true, "On peut le vérifier avec des données : les statistiques fiscales et les enquêtes le montrent."],
      ["Une société est plus juste quand les écarts de revenu sont faibles.", false, "Il dit ce qui devrait être. Des faits peuvent éclairer le débat, mais pas le trancher : il existe plusieurs théories de la justice, et elles ne répondent pas toutes de la même façon."],
      ["Les revenus sont plus inégalement répartis aux États-Unis qu’en Suisse.", true, "On peut le vérifier avec des données, par exemple en comparant les coefficients de Gini publiés par l’OCDE."],
      ["Si le rendement du capital reste supérieur à la croissance, la concentration des patrimoines devrait continuer d’augmenter.", true, "C’est une prévision, que l’on pourra confronter aux chiffres. « Devrait » exprime ici une attente, pas un souhait."]] },
  ]);
  /* =========================== COMPLÉMENTS : séries portées à douze exercices (novembre 2026) =========================== */
  X.add([
  /* ----- Niveau 1 ----- */
  { id: "in1-graph-redistribution", theme: "inegalites", niveau: 1, type: "graphique",
    titre: "Avant et après la redistribution", competence: "Comparer deux séries de revenus sur un graphique en barres.",
    enonce: P("On classe les ménages d’un pays en cinq groupes de même taille, du plus pauvre (1) au plus riche (5). Le graphique donne le revenu mensuel moyen de chaque groupe, en milliers de francs, avant puis après les impôts et les prestations sociales.", "Que montre le graphique ?"),
    fig: () => X.barres({ cats: ["1", "2", "3", "4", "5"], vals: [1.5, 3.5, 5.5, 8, 16], vals2: [2.8, 3.8, 5.2, 7, 12.5], noms: ["Avant", "Après"], ymax: 18, dec: 1, aria: "Revenu moyen des cinq groupes avant et après redistribution", caption: "Revenu mensuel moyen en milliers de francs. Données inventées pour l’exercice." }),
    options: ["Les groupes 1 et 2 reçoivent plus qu’ils ne paient, les trois autres l’inverse.", "Les cinq groupes ont un revenu plus faible après les impôts et les prestations.", "Après la redistribution, les cinq groupes disposent du même revenu.", "Après la redistribution, le groupe 5 garde un revenu 12,5 fois plus élevé que le groupe 1."], c: 0,
    pourquoi: [null, "Le revenu des groupes 1 et 2 augmente, de 1 500 à 2 800 francs et de 3 500 à 3 800 francs. Les prestations qu’ils reçoivent dépassent leurs impôts.", "Les écarts se réduisent sans disparaître. Après redistribution, les revenus vont encore de 2 800 à 12 500 francs.", "12,5 est le revenu du groupe 5 en milliers de francs. Rapporté à celui du groupe 1, il vaut 12,5 ÷ 2,8, soit environ 4,5 fois."],
    explication: P("Pour chaque groupe, on compare la barre « Avant » et la barre « Après ». Les groupes 1 et 2 gagnent à la redistribution. Les groupes 3, 4 et 5 y contribuent, le groupe 5 pour 3 500 francs par mois.", "L’écart entre les extrêmes passe d’un rapport de 16 ÷ 1,5 ≈ 10,7 à un rapport de 12,5 ÷ 2,8 ≈ 4,5. La redistribution réduit les inégalités de revenu sans les supprimer.") },

  { id: "in1-effort", theme: "inegalites", niveau: 1, type: "calcul",
    titre: "Le poids du loyer dans le budget", competence: "Calculer la part d’une dépense dans un revenu.",
    gen: () => { let rev, loyer; do { rev = rnd(35, 95) * 100; loyer = rnd(11, 22) * 100; } while (loyer > 0.45 * rev || loyer < 0.15 * rev); return { rev, loyer }; },
    enonce: (p) => P(`Un ménage dispose d’un revenu de <b>${fmt(p.rev)} francs</b> par mois et paie un loyer de <b>${fmt(p.loyer)} francs</b>.`, "Quelle part de son revenu consacre-t-il au loyer ? Arrondissez à une décimale."),
    champs: [{ label: "Part du loyer", unite: "%", tol: 0.1 }],
    reponses: (p) => [Math.round(p.loyer / p.rev * 1000) / 10],
    indice: "Une part se calcule en divisant la dépense par le revenu, puis en multipliant par 100.",
    correction: (p) => P(`Part du loyer = ${fmt(p.loyer)} ÷ ${fmt(p.rev)} × 100`, `≈ <b>${fmt(p.loyer / p.rev * 100, 1)} %</b>.`, "Cette part est en général plus élevée pour les ménages modestes. Un même loyer pèse plus lourd sur un petit revenu, et il reste moins pour les autres dépenses. C’est pourquoi une hausse des loyers creuse les écarts de niveau de vie, même si elle est la même pour tous.") },

  { id: "in1-doc-impot", theme: "inegalites", niveau: 1, type: "document",
    titre: "Un impôt qui pèse plus sur les petits revenus", competence: "Reconnaître un impôt progressif, proportionnel ou régressif à partir d’un tableau.",
    enonce: P("Le tableau donne, pour trois ménages, le revenu annuel et le montant de taxe sur la valeur ajoutée payé en une année sur leurs achats.") +
      `<table><thead><tr><th>Ménage</th><th>Revenu annuel (fr.)</th><th>Taxe payée (fr.)</th></tr></thead><tbody><tr><td>A</td><td>30 000</td><td>1 800</td></tr><tr><td>B</td><td>60 000</td><td>3 000</td></tr><tr><td>C</td><td>120 000</td><td>4 800</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Rapportée au revenu, comment cette taxe se comporte-t-elle ?"),
    options: ["Elle est régressive, car elle prend 6 % du revenu le plus bas et 4 % du plus élevé.", "Elle est progressive, car le ménage le plus riche paie le montant le plus élevé.", "Elle est proportionnelle, car le taux appliqué aux achats est le même pour tous.", "Elle est progressive, car le montant payé double chaque fois que le revenu double."], c: 0,
    pourquoi: [null, "Le montant payé augmente bien avec le revenu. Mais un impôt est progressif quand la part du revenu prélevée augmente, et ici elle diminue.", "Le taux sur les achats est le même, mais les ménages aisés ne dépensent pas tout leur revenu. Rapportée au revenu, la taxe pèse donc moins sur eux.", "Quand le revenu double de 30 000 à 60 000 francs, la taxe passe de 1 800 à 3 000 francs. Elle ne double pas, et sa part dans le revenu baisse."],
    explication: P("Part du revenu prélevée : 1 800 ÷ 30 000 = <b>6 %</b> pour A, 3 000 ÷ 60 000 = <b>5 %</b> pour B, 4 800 ÷ 120 000 = <b>4 %</b> pour C.", "La part diminue quand le revenu augmente. La taxe est <b>régressive</b> par rapport au revenu, alors que son taux sur les achats est le même pour tous.", "L’explication tient à l’épargne. Un ménage modeste dépense presque tout ce qu’il gagne, un ménage aisé en épargne une partie, qui échappe à la taxe. C’est une des raisons pour lesquelles les biens de première nécessité sont souvent taxés à un taux réduit.") },

  /* ----- Niveau 2 ----- */
  { id: "in2-graph-lorenz", theme: "inegalites", niveau: 2, type: "graphique", notion: "courbe-kuznets",
    titre: "Lire une courbe de Lorenz", competence: "Lire des parts cumulées sur une courbe de Lorenz et comparer deux pays.",
    enonce: P("Le graphique présente les courbes de Lorenz de deux pays. En abscisse figure la part cumulée de la population, classée du plus pauvre au plus riche, en ordonnée la part cumulée du revenu total.", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 106, ymax: 108, ylab: "Part du revenu (%)", xlab: "Part de la population (%)", aria: "Courbes de Lorenz de deux pays, celle du pays B étant plus éloignée de la diagonale",
      gx: [[40, "40"], [80, "80"], [100, "100"]], gy: [[10, "10"], [20, "20"], [42, "42"], [58, "58"], [100, "100"]], reperes: [[40, 20], [40, 10], [80, 58], [80, 42]],
      lignes: [{ pts: [[0, 0], [100, 100]], col: "g", dash: true, lab: "égalité parfaite", at: [50, 50], dx: -150, dy: -22 }, { pts: [[0, 0], [20, 8], [40, 20], [60, 36], [80, 58], [100, 100]], col: "d" }, { pts: [[0, 0], [20, 3], [40, 10], [60, 22], [80, 42], [100, 100]], col: "o" }],
      points: [{ x: 40, y: 20, col: "d" }, { x: 80, y: 58, col: "d" }, { x: 40, y: 10, col: "o" }, { x: 80, y: 42, col: "o" }],
      caption: "La courbe verte est celle du pays A, la courbe dorée celle du pays B. Données inventées pour l’exercice." }),
    options: ["Dans le pays B, les 40 % les plus pauvres reçoivent 10 % du revenu, contre 20 % dans le pays A.", "Le pays A est le plus inégalitaire, car sa courbe est la plus proche de la droite d’égalité parfaite.", "Dans le pays B, les 20 % les plus riches reçoivent 42 % du revenu, contre 58 % dans le pays A.", "Dans les deux pays, 40 % de la population reçoit 40 % du revenu, comme sur la diagonale."], c: 0,
    pourquoi: [null, "C’est l’inverse. Plus la courbe est proche de la diagonale, plus les revenus sont également répartis. La courbe du pays A en est la plus proche.", "42 % et 58 % sont les parts reçues par les 80 % les moins riches. Les 20 % les plus riches reçoivent le reste, soit 58 % dans le pays B et 42 % dans le pays A.", "La diagonale décrit une égalité parfaite, qui n’existe dans aucun des deux pays. Sur les courbes, les 40 % les plus pauvres reçoivent 20 % et 10 % du revenu."],
    explication: P("Un point de la courbe de Lorenz se lit ainsi. Les x % les plus pauvres de la population reçoivent y % du revenu total.", "Dans le pays A, les 40 % les plus pauvres reçoivent <b>20 %</b> du revenu et les 20 % les plus riches 100 − 58 = 42 %. Dans le pays B, les 40 % les plus pauvres en reçoivent <b>10 %</b> et les 20 % les plus riches 100 − 42 = 58 %. Le pays B est donc le plus inégalitaire.", "Plus la courbe s’éloigne de la diagonale, plus la répartition est inégale. Le coefficient de Gini mesure cet éloignement. Il vaut la surface comprise entre la diagonale et la courbe, rapportée à la surface du triangle situé sous la diagonale.") },

  { id: "in2-gini-quintiles", theme: "inegalites", niveau: 2, type: "calcul", notion: "courbe-kuznets",
    titre: "Calculer un coefficient de Gini par quintiles", competence: "Calculer un coefficient de Gini à partir de parts de revenu par la méthode des trapèzes.",
    gen: () => ({ q: pick([[8, 12, 16, 22, 42], [5, 10, 15, 22, 48], [10, 14, 18, 23, 35], [4, 8, 14, 24, 50], [6, 11, 17, 24, 42]]) }),
    enonce: (p) => P("On classe les ménages d’un pays en cinq groupes de même taille, du plus pauvre au plus riche. Voici la part du revenu total que reçoit chaque groupe.") +
      `<table><thead><tr><th>Groupe</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th></tr></thead><tbody><tr><th>Part du revenu</th>${p.q.map((x) => `<td>${x} %</td>`).join("")}</tr></tbody></table>` +
      P("Calculez les parts cumulées, puis le coefficient de Gini par la méthode des trapèzes : G = 1 − 0,2 × la somme, pour les cinq groupes, de (part cumulée avant le groupe + part cumulée après le groupe), les parts étant écrites en fractions. Arrondissez à trois décimales."),
    champs: [{ label: "Coefficient de Gini", unite: "", tol: 0.002 }],
    reponses: (p) => { let c = 0, s = 0; p.q.forEach((x) => { s += 2 * c + x; c += x; }); return [Math.round((1 - 0.2 * s / 100) * 1000) / 1000]; },
    indice: "Commencez par le tableau des parts cumulées. Pour le premier groupe, la part cumulée « avant » vaut 0.",
    correction: (p) => { const cum = []; let c = 0; p.q.forEach((x) => { c += x; cum.push(c); }); const termes = cum.map((v, k) => (k ? cum[k - 1] : 0) + v), s = termes.reduce((a, b) => a + b, 0); return P(`Parts cumulées : ${cum.map((v) => v + " %").join(", ")}.`, `Sommes à former : ${termes.map((t, k) => `${k ? cum[k - 1] : 0} + ${cum[k]} = ${t}`).join(" ; ")}. Leur total vaut ${s} %, soit ${fmt(s / 100, 2)} en fraction.`, `G = 1 − 0,2 × ${fmt(s / 100, 2)} = <b>${fmt(1 - 0.2 * s / 100, 3)}</b>.`, "Chaque terme correspond à la surface d’un trapèze situé sous la courbe de Lorenz. Le coefficient vaut 0 si tous les groupes reçoivent la même part. Avec cinq groupes, il ne peut pas dépasser 0,8, valeur atteinte quand le dernier groupe reçoit tout. Le calcul sous-estime un peu le vrai coefficient, car il ignore les inégalités à l’intérieur de chaque groupe."); } },

  { id: "in2-doc-deciles", theme: "inegalites", niveau: 2, type: "document",
    titre: "Lire des déciles de salaires", competence: "Interpréter des déciles et calculer un rapport interdécile.",
    enonce: P("Une enquête donne trois repères de la répartition des salaires mensuels bruts à plein temps dans un pays.") +
      `<table><thead><tr><th>Repère</th><th>Salaire (fr.)</th></tr></thead><tbody><tr><td>Premier décile (D1)</td><td>4 200</td></tr><tr><td>Médiane (D5)</td><td>6 800</td></tr><tr><td>Neuvième décile (D9)</td><td>11 800</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quelle lecture est correcte ?"),
    options: ["Neuf salariés sur dix gagnent moins de 11 800 francs, soit 2,8 fois le seuil du premier décile.", "Un salarié sur dix gagne 4 200 francs, qui est le plus bas salaire versé dans le pays.", "La moitié des salariés gagne plus de 11 800 francs, le salaire médian des cadres.", "Le salaire moyen du pays est de 6 800 francs, puisque c’est la valeur du milieu."], c: 0,
    pourquoi: [null, "Le premier décile est un seuil. Un salarié sur dix gagne 4 200 francs ou moins, et certains gagnent bien moins. Ce n’est pas le plus bas salaire du pays.", "C’est la médiane, 6 800 francs, qui partage les salariés en deux moitiés. Seul un salarié sur dix dépasse 11 800 francs.", "6 800 francs est la médiane, pas la moyenne. Comme quelques très hauts salaires tirent la moyenne vers le haut, celle-ci est en général supérieure à la médiane."],
    explication: P("Les déciles partagent les salariés en dix groupes égaux. <b>D1</b> est le salaire au-dessous duquel se trouvent 10 % des salariés, <b>D9</b> celui au-dessous duquel se trouvent 90 % d’entre eux. La médiane en laisse la moitié de chaque côté.", "Rapport interdécile : D9 ÷ D1 = 11 800 ÷ 4 200 ≈ <b>2,8</b>. Le seuil des hauts salaires vaut près de trois fois celui des bas salaires.", "Cet indicateur ignore volontairement les extrêmes. Il ne dit rien des très hauts salaires, au-delà de D9, là où les écarts se sont le plus creusés dans beaucoup de pays.") },

  { id: "in2-vf-mesures", theme: "inegalites", niveau: 2, type: "vf", notion: "courbe-kuznets",
    titre: "Ce que mesure le coefficient de Gini", competence: "Prévoir comment le coefficient de Gini réagit à un changement de la répartition.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Un coefficient de Gini de 0,30 signifie que 30 % de la population est pauvre.", false, "Le coefficient mesure l’inégalité de la répartition, sur une échelle de 0 à 1. Il ne compte pas les personnes pauvres et ne dit rien du niveau des revenus."],
      ["Si tous les revenus d’un pays doublent, son coefficient de Gini ne change pas.", true, "Les parts de chacun dans le revenu total restent les mêmes. Le coefficient ne dépend que de ces parts, pas du niveau des revenus."],
      ["Deux pays peuvent avoir le même coefficient de Gini avec des répartitions différentes.", true, "Leurs courbes de Lorenz peuvent se croiser et délimiter la même surface. L’un peut avoir plus de très pauvres, l’autre plus de très riches."],
      ["Un transfert de revenu d’un ménage riche vers un ménage pauvre fait monter le coefficient de Gini.", false, "Il le fait baisser. Tout transfert d’un plus riche vers un plus pauvre, qui n’inverse pas leur classement, rapproche la courbe de Lorenz de la diagonale."]
    ] },

  /* ----- Niveau 3 ----- */
  { id: "in3-doc-mincer", theme: "inegalites", niveau: 3, type: "document",
    titre: "Lire une équation de salaire", competence: "Interpréter les coefficients d’une régression en logarithme du salaire.",
    enonce: P("Une étude estime sur 12 000 salariés une équation de salaire à la manière de Jacob Mincer. La variable expliquée est le logarithme du salaire horaire.") +
      `<table><thead><tr><th>Variable</th><th>Coefficient</th><th>Écart-type</th></tr></thead><tbody><tr><td>Années d’études</td><td>0,080</td><td>0,004</td></tr><tr><td>Années d’expérience</td><td>0,030</td><td>0,003</td></tr><tr><td>Années d’expérience au carré</td><td>−0,0005</td><td>0,0001</td></tr><tr><td>Femme (1 si oui)</td><td>−0,120</td><td>0,010</td></tr><tr><td>Constante</td><td>2,90</td><td>0,05</td></tr></tbody></table><p class="ex-source">R² = 0,34. Résultats inventés pour l’exercice, d’un ordre de grandeur courant dans ce type d’étude.</p>` +
      P("Quelle interprétation est correcte ?"),
    options: ["Une année d’études de plus va avec un salaire supérieur d’environ 8 %, et les femmes gagnent environ 11 % de moins à études et expérience égales.", "Une année d’études de plus rapporte 0,08 franc de l’heure, et les femmes gagnent 0,12 franc de moins que les hommes.", "Le modèle explique 34 % des salaires, ce qui prouve que 66 % de l’écart entre femmes et hommes vient de la discrimination.", "Chaque année d’expérience augmente le salaire de 3 %, ce qui donne une hausse de 90 % après trente ans de carrière."], c: 0,
    pourquoi: [null, "La variable expliquée est un logarithme. Les coefficients se lisent donc comme des variations en proportion du salaire, et non en francs.", "Le R² dit quelle part des différences de salaire entre individus le modèle reproduit. Il ne renseigne pas sur l’origine de l’écart entre femmes et hommes, que mesure le coefficient de la variable « Femme ».", "Le terme au carré a un coefficient négatif. Le gain d’une année d’expérience diminue avec l’ancienneté et s’annule après 0,030 ÷ (2 × 0,0005) = 30 ans. Après trente ans, l’effet cumulé est de 0,030 × 30 − 0,0005 × 30² = 0,45, soit environ 57 % et non 90 %."],
    explication: P("Dans une équation en logarithme, un coefficient b se lit comme une variation d’environ 100 × b %. Une année d’études de plus est associée à un salaire supérieur d’environ <b>8 %</b>.", "Le coefficient de −0,120 correspond à un écart de e<sup>−0,12</sup> − 1 ≈ <b>−11 %</b> pour une femme, à études et expérience égales. Tous les coefficients sont précis, puisqu’ils valent plusieurs fois leur écart-type.", "L’interprétation est discutée. Pour la théorie du capital humain de Gary Becker et Jacob Mincer, le coefficient des études mesure un gain de productivité. Pour la théorie du signal de Michael Spence, le diplôme révèle surtout des aptitudes déjà présentes. L’écart restant entre femmes et hommes peut contenir de la discrimination, mais aussi des différences non mesurées, comme la branche ou le temps partiel passé, qui peuvent elles-mêmes résulter d’inégalités.") },

  { id: "in3-saez", theme: "inegalites", niveau: 3, type: "calcul", notion: "optimum-pareto",
    titre: "Le taux d’imposition des très hauts revenus", competence: "Appliquer une formule d’imposition optimale et étudier sa sensibilité à l’élasticité.",
    gen: () => ({ a: pick([1.5, 2]), e: pick([0.2, 0.25, 0.5]), e2: pick([0.8, 1]) }),
    enonce: (p) => P(`Pour les très hauts revenus, Peter Diamond et Emmanuel Saez ont proposé en 2011 le taux marginal d’imposition qui rapporte le plus de recettes : <b>τ = 1 ÷ (1 + a × e)</b>. Le paramètre a décrit la forme du haut de la répartition des revenus, et e est l’élasticité du revenu déclaré par rapport à ce qui reste après impôt.`, `Prenez <b>a = ${fmt(p.a)}</b>. Calculez ce taux pour <b>e = ${fmt(p.e)}</b>, puis pour <b>e = ${fmt(p.e2)}</b>. Arrondissez à une décimale.`),
    champs: [{ label: "Taux pour la première élasticité", unite: "%", tol: 0.1 }, { label: "Taux pour la seconde élasticité", unite: "%", tol: 0.1 }],
    reponses: (p) => [Math.round(1000 / (1 + p.a * p.e)) / 10, Math.round(1000 / (1 + p.a * p.e2)) / 10],
    indice: "Calculez d’abord le produit a × e, ajoutez 1, puis prenez l’inverse.",
    correction: (p) => P(`On applique τ = 1 ÷ (1 + a × e) avec a = ${fmt(p.a)}.`, `Avec e = ${fmt(p.e)} : τ = 1 ÷ (1 + ${fmt(p.a)} × ${fmt(p.e)}) = 1 ÷ ${fmt(1 + p.a * p.e, 3)} ≈ <b>${fmt(100 / (1 + p.a * p.e), 1)} %</b>.`, `Avec e = ${fmt(p.e2)} : τ = 1 ÷ ${fmt(1 + p.a * p.e2, 3)} ≈ <b>${fmt(100 / (1 + p.a * p.e2), 1)} %</b>.`, "Tout dépend de l’élasticité. Si les hauts revenus réagissent peu à l’impôt, le taux qui maximise les recettes est très élevé. S’ils réagissent fortement, en travaillant moins, en déplaçant leurs revenus ou en quittant le pays, il est bien plus bas.", "Diamond et Saez retiennent une élasticité faible et concluent à un taux supérieur à 70 %. D’autres économistes, dans la lignée de Martin Feldstein, jugent l’élasticité plus forte à long terme, parce que l’impôt décourage aussi la création d’entreprises et l’effort de formation. Un petit pays ouvert, dont les contribuables fortunés peuvent partir, fait face à une élasticité plus élevée qu’un grand pays. La formule ne dit enfin que ce qui rapporte le plus à l’État. Elle n’accorde aucun poids au revenu des contribuables concernés.") },

  { id: "in3-graph-laffer", theme: "inegalites", niveau: 3, type: "graphique",
    titre: "La courbe de Laffer", competence: "Lire une courbe de recettes fiscales et discuter la position d’un pays sur cette courbe.",
    enonce: P("Le graphique donne les recettes d’un impôt selon son taux. Deux situations sont repérées, A et B.", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 108, ymax: 118, ylab: "Recettes fiscales", xlab: "Taux d’imposition (%)", aria: "Courbe de Laffer en cloche, avec un maximum pour un taux de 50 pour cent",
      gx: [[30, "30"], [50, "50"], [70, "70"], [100, "100"]], reperes: [[30, 84], [70, 84]],
      lignes: [{ f: (t) => 0.04 * t * (100 - t), de: 0, a: 100, col: "d" }],
      points: [{ x: 30, y: 84, lab: "A", dx: -10, dy: -10, anc: "end" }, { x: 70, y: 84, lab: "B", dx: 10, dy: -10 }, { x: 50, y: 100, col: "o" }],
      caption: "Courbe théorique. La position du sommet dépend de la façon dont les contribuables réagissent à l’impôt." }),
    options: ["Une baisse du taux augmente les recettes au point B et les réduit au point A.", "Une baisse du taux augmente les recettes aux deux points, car elle stimule l’activité.", "Les recettes sont les mêmes en A et en B, le choix du taux est donc sans importance.", "Les recettes augmentent avec le taux et atteignent leur maximum à 100 %."], c: 0,
    pourquoi: [null, "Au point A, le pays est sur la partie montante de la courbe. Baisser le taux y réduit les recettes, même si l’activité augmente un peu.", "Les recettes sont égales, mais pas la situation des contribuables. En B, ils paient un taux de 70 % pour une activité bien plus faible qu’en A. Le point A est préférable pour tous.", "À 100 %, personne n’a intérêt à déclarer un revenu, et les recettes tombent à zéro. La courbe redescend après son sommet."],
    explication: P("À 0 % comme à 100 %, l’impôt ne rapporte rien. Entre les deux, les recettes passent par un <b>maximum</b>, ici à 50 %. À gauche du sommet, relever le taux augmente les recettes. À droite, il les réduit, parce que la base imposable recule plus vite que le taux ne monte.", "Au point B, une baisse du taux rapporte donc davantage. Au point A, elle coûte des recettes.", "La forme de la courbe fait consensus, la position des pays beaucoup moins. Arthur Laffer et les économistes de l’offre ont soutenu vers 1980 que les États-Unis étaient à droite du sommet. Les baisses d’impôts qui ont suivi ont creusé le déficit, et la plupart des estimations placent les pays développés à gauche du sommet pour l’impôt sur le revenu dans son ensemble. Le débat reste ouvert pour les taux les plus élevés et pour les bases très mobiles.") },

  { id: "in3-red-justice", theme: "inegalites", niveau: 3, type: "redaction", notion: "capabilites",
    titre: "Qu’est-ce qu’une répartition juste ?", competence: "Comparer plusieurs théories de la justice et leurs conséquences pour la redistribution.",
    enonce: P("Dans les pays de l’OCDE, les impôts et les prestations réduisent les inégalités de revenu d’un quart environ, avec de grands écarts d’un pays à l’autre. Derrière ces choix se trouvent des conceptions différentes de ce qu’est une répartition juste.", "<b>Consigne :</b> comparez au moins trois conceptions en les rattachant à leurs auteurs (utilitarisme de Bentham et de Pigou, principe de différence de Rawls, justice des procédures chez Nozick ou Hayek, capabilités de Sen, exploitation chez Marx). Pour chacune, dites ce qu’elle cherche à égaliser ou à garantir, ce qu’elle conclut sur la redistribution et l’objection principale qu’on lui oppose. Dites sur quelle hypothèse au moins deux de ces conceptions s’opposent. Appliquez-les à un même exemple, puis prenez position. Longueur attendue, 20 à 30 lignes."),
    criteres: ["La réponse présente au moins trois conceptions et nomme leurs auteurs.", "Elle dit ce que chacune cherche à égaliser ou à garantir (bien-être total, sort des plus défavorisés, droits et procédures, libertés réelles, fruit du travail).", "Elle indique ce que chacune conclut sur la redistribution.", "Elle formule pour chacune au moins une objection.", "La réponse nomme au moins deux écoles ou auteurs et l’hypothèse qui les sépare.", "Elle applique ces conceptions à un même exemple et se termine par une prise de position explicite, justifiée par un des arguments présentés."],
    corrige: P("<b>Utilitarisme.</b> Pour Bentham, puis Pigou, une société juste maximise la somme des bien-être. Comme un franc de plus compte davantage pour un pauvre que pour un riche, transférer du second au premier augmente le total. La redistribution n’a de limite que son effet sur l’incitation à produire. L’objection est que la somme peut justifier le sacrifice de quelques-uns au profit du grand nombre.", "<b>Rawls.</b> Derrière un « voile d’ignorance », sans connaître sa place future, chacun choisirait des libertés égales et n’accepterait les inégalités que si elles améliorent le sort des plus défavorisés. Une inégalité qui stimule la production est donc acceptable si les plus pauvres y gagnent. L’objection est que cette priorité absolue donnée aux plus défavorisés suppose une prudence extrême.", "<b>Nozick et Hayek.</b> Une répartition est juste si elle résulte d’acquisitions et d’échanges libres, quel qu’en soit le résultat. L’impôt redistributif viole le droit de chacun sur le fruit de son activité. Pour Hayek, parler de justice d’un résultat que personne n’a voulu n’a pas de sens. L’objection est que les positions de départ, héritage compris, ne résultent pas toutes de procédures justes.", "<b>Sen.</b> Ce qui compte n’est ni le revenu ni le bien-être déclaré, mais ce que chacun peut réellement faire et être. Deux personnes au même revenu n’ont pas les mêmes libertés si l’une est malade ou isolée. La politique doit viser la santé, l’éducation et l’accès, pas seulement les transferts. L’objection est que la liste des capabilités à garantir reste à définir.", "<b>Marx.</b> L’inégalité naît dans la production. Le salarié crée plus de valeur qu’il n’en reçoit, et la différence revient au détenteur du capital. Redistribuer après coup ne touche pas à cette cause, qui tient à la propriété des moyens de production. L’objection est que les économies sans propriété privée des moyens de production ont connu d’autres inégalités, entre dirigeants et dirigés.", "<b>Ce qui les oppose.</b> L’utilitarisme et Rawls s’opposent sur l’agrégation : le premier suppose que les bien-être des personnes s’additionnent, le second refuse de compenser le sacrifice des uns par le gain des autres. Rawls et Nozick s’opposent sur le statut des talents et des positions de départ : pour Rawls, ils relèvent d’une loterie sociale et naturelle dont on corrige le résultat, pour Nozick, ils appartiennent à chacun. Sen s’oppose à Rawls sur ce qu’il faut égaliser : des biens premiers identiques ne donnent pas les mêmes libertés réelles, puisque la capacité de les convertir varie d’une personne à l’autre. Marx s’oppose à tous sur le lieu de la justice : pour lui, elle se joue dans la propriété des moyens de production et non dans la répartition des revenus.", "<b>Exemple et prise de position possible.</b> Face à un impôt sur les grandes successions, l’utilitariste et Rawls l’approuvent s’il finance les plus modestes sans trop réduire l’épargne. Nozick le rejette, sauf si la fortune a été acquise injustement. Sen demande si son produit élargit les libertés réelles, par exemple par l’éducation. La position de Rawls paraît la plus convaincante, parce qu’elle admet des inégalités utiles tout en donnant un critère pour les limiter. Elle gagne à être complétée par Sen sur ce qu’il faut mesurer.") },
]);
  /* =========================== FIN DES COMPLÉMENTS =========================== */
})();
